xml.Script:
        clWhite  := 'FFFFFF';
        clGreen  := '009600';
        clYellow := 'FFFF00';
        clBlue   := '0000C8';
        clArrow  := '000000';

        Colors[0] := clWhite;
        Colors[1] := clGreen;
        Colors[2] := clYellow;
        Colors[3] := clBlue;

        W := 0.5;

        R := W;
        H := W;
        D := H / 2;
        N := 48;
        M := N;
        for i := 0 to M - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

        function GetInt(): integer;
        begin
          p := Pos(',', sProfile);
          if p = 0 then begin
            substr := sProfile;
            sProfile := '';
          end else begin
            substr := copy(sProfile, 1, p-1);
            Delete(sProfile, 1, p);
          end;
          Result := StrToInt(substr);
        end;

//Size 85x85
//Polygon -39,-2, 31,-2, 11,-22, 14,-25, 39,0, 14,25, 11,22, 31,2, -39,2
        // Arrow
        sProfile := '-39,-2, 31,-2, 11,-22, 14,-25, 39,0, 14,25, 11,22, 31,2, -39,2';
        ProfileSize := 85;
        pCount := 0;
        while Length(sProfile) > 0 do begin
          px[pCount] := (GetInt / ProfileSize * R)*0.3;
          pz[pCount] := (GetInt / ProfileSize * R)*0.3 + D/2;
          Inc(pCount);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
